package com.luminor.tavernquest.data.repository
import com.luminor.tavernquest.data.local.database.dao.*;import com.luminor.tavernquest.data.local.database.entity.DailyContractEntity;import com.luminor.tavernquest.data.mapper.*;import com.luminor.tavernquest.data.seed.ContractSeed;import com.luminor.tavernquest.domain.model.*;import com.luminor.tavernquest.domain.repository.ContractRepository;import com.luminor.tavernquest.domain.rules.*;import kotlinx.coroutines.flow.map
class ContractRepositoryImpl(private val templates:ContractTemplateDao,private val daily:DailyContractDao):ContractRepository{private val gen=DailyBoardGenerator();private val limit=ContractLimitRule();override suspend fun ensureSeeded(){if(templates.count()==0)templates.insertAll(ContractSeed.all.map{it.toEntity()})};override suspend fun generateBoard(date:String,tavernId:String){ensureSeeded();if(daily.getByDate(date).isNotEmpty())return;val chosen=gen.generate(templates.getEnabled().map{it.toDomain()},date);daily.insertAll(chosen.map{DailyContractEntity("$date:${it.id}",it.id,tavernId,date,ContractStatus.AVAILABLE.name,null,null)})};override suspend fun getBoard(date:String)=daily.getByDate(date).map{it.toDomain()};override fun observeBoard(date:String)=daily.observeByDate(date).map{list->list.map{it.toDomain()}};override suspend fun get(id:String)=daily.getById(id)?.toDomain();override suspend fun accept(id:String,date:String):Boolean{if(!limit.canAccept(daily.countAcceptedByDate(date)))return false;val c=daily.getById(id)?.contract?:return false;if(c.status!=ContractStatus.AVAILABLE.name)return false;daily.updateStatus(id,ContractStatus.ACCEPTED.name,System.currentTimeMillis(),null);return true};override suspend fun abandon(id:String){val c=daily.getById(id)?.contract?:return;daily.updateStatus(id,ContractStatus.ABANDONED.name,c.acceptedAt,null)};override suspend fun expireBefore(date:String)=daily.expireBefore(date)}
